// Prototype localization. Detection uses preferred languages, never IP/geolocation.
const localeChoices=[['system','自动 / Follow system'],['zh-CN','简体中文'],['en','English']];
const localeNames={'zh-CN':'简体中文',en:'English'};
function normalizeLanguage(value){return ({'简体中文':'zh-CN',English:'en','跟随系统':'system'})[value]||(['system','zh-CN','en'].includes(value)?value:'system');}
function browserLanguages(){return Array.from(navigator.languages?.length?navigator.languages:[navigator.language||'en']);}
function detectLanguage(languages=browserLanguages()){
  for(const raw of languages){const tag=String(raw).replaceAll('_','-').toLowerCase();
    if(/^zh(?:$|-)/.test(tag)){if(/(?:hant|tw|hk|mo)/.test(tag))continue;return {locale:'zh-CN',matched:raw,fallback:false};}
    if(/^en(?:$|-)/.test(tag))return {locale:'en',matched:raw,fallback:false};
  }
  return {locale:'en',matched:null,fallback:true};
}
function activeLocale(){const conf=state.route.startsWith('settings/')||state.route.startsWith('onboarding/')?draft:saved;return normalizeLanguage(conf.language)==='system'?detectLanguage().locale:normalizeLanguage(conf.language);}
function t(source){if(activeLocale()==='zh-CN')return source;return english[source]||translateDynamic(source);}
function translateDynamic(s){return s.replace(/^贴图默认：(.+)$/, 'Pin shortcut: $1').replace(/^完成动作：(.+)$/,(_,v)=>`Finish action: ${english[v]||v}`).replace(/^自动保存：(开启|关闭)　·　截图历史：(开启|关闭)$/,(_,a,b)=>`Auto-save: ${a==='开启'?'On':'Off'} · Capture history: ${b==='开启'?'On':'Off'}`).replace(/^目录：(.+)$/, 'Folder: $1').replace(/^格式：(.+)$/, 'Format: $1').replace(/^首次安装引导 \/ (\d+) of 6$/,'First-run setup / $1 of 6').replace(/^(\d+)\. (欢迎|热键|默认行为|外观|试一次|完成)$/,(_,n,v)=>`${n}. ${english[v]||v}`).replace(/^动作：(.+)$/,(_,v)=>`Action: ${english[v]||v}`).replace(/^与“(.+)”冲突；旧绑定未改变。$/,(_,v)=>`Conflicts with “${english[v]||v}”. Existing shortcut kept.`).replace(/^主色只用于选择、焦点和主要操作。$/,'Accent color is used only for selection, focus and primary actions.').replace(/^(.*) px · 示例像素$/,'$1 px · sample pixels').replace(/^工具条已应用，选区与标注保持不变。$/,'Toolbar applied. Selection and annotations kept.').replace(/^示例截图 0(\d+)$/,'Sample capture 0$1').replace(/^今天 (.+)$/,'Today $1').replace(/^(.+) 秒$/,'$1 s').replace(/^(.+) 天$/,'$1 days');}
function languageControls(onboarding=false){const detected=detectLanguage(),selected=normalizeLanguage(draft.language),resolved=selected==='system'?detected.locale:selected;const region=browserLanguages()[0]||'en';let example;try{example=new Intl.DateTimeFormat(region,{dateStyle:'medium',timeStyle:'short'}).format(new Date('2026-10-18T06:32:00Z'));}catch{example=new Intl.DateTimeFormat('en',{dateStyle:'medium',timeStyle:'short'}).format(new Date('2026-10-18T06:32:00Z'));}
return `<section class="language-panel"><div class="spread"><label for="ui-language"><b>${t('界面语言')}</b></label><select id="ui-language" data-locale-choice>${localeChoices.map(([v,n])=>`<option value="${v}" ${selected===v?'selected':''}>${v==='system'?t('自动 / 跟随系统'):n}</option>`).join('')}</select></div><div class="language-status"><div>${t('检测到的首选语言：')} <code>${esc(browserLanguages().join(', '))}</code></div><div>${t('当前界面：')} ${localeNames[resolved]} · ${selected==='system'?t('自动匹配'):t('手动选择优先')}</div>${detected.fallback&&selected==='system'?`<div class="note">${t('首选语言暂无翻译，已回退到 English。你可以随时切换。')}</div>`:''}<div>${t('日期与时间示例：')} ${esc(example)}</div></div><small>${t(onboarding?'首次引导自动读取系统首选语言；手动选择会被记住。无需联网，也不按所在地猜测语言。':'自动模式按系统语言偏好顺序匹配已有翻译；手动选择优先于自动检测。日期遵循地区偏好，与界面语言分开。')}</small><details><summary>${t('其他语言与扩展')}</summary><p>${t('当前原型提供简体中文和 English。繁體中文、日本語、한국어、Deutsch、Français、Español、Português 和 العربية 是后续语言包计划；未完成翻译的语言不会伪装成已支持。')}</p><p>${t('未来原生版本读取操作系统首选语言列表；当前 HTML 使用浏览器 navigator.languages 模拟。右到左布局随对应语言包另行验收。')}</p></details></section>`;}
const localizedSources=new WeakMap();
function localizeDom(){const locale=activeLocale();document.documentElement.lang=locale;document.documentElement.dir='ltr';document.title=locale==='en'?'Glint · Interactive prototype':'拾光 Glint · 全流程交互原型';const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walk.nextNode()){const parent=node.parentElement;if(!parent||parent.closest('script,style,code,kbd,textarea,svg text,[data-no-i18n]')||parent.matches('input'))continue;const current=node.nodeValue;let record=localizedSources.get(node);if(!record||current!==record.last){record={source:current,last:current};localizedSources.set(node,record);}const source=record.source;const stripped=source.trim();const translated=locale==='zh-CN'?source:source.replace(stripped,t(stripped));if(node.nodeValue!==translated)node.nodeValue=translated;record.last=translated;}
for(const el of document.querySelectorAll('[title],[aria-label],[placeholder]')){if(el.closest('[data-no-i18n]'))continue;for(const attr of ['title','aria-label','placeholder']){if(!el.hasAttribute(attr))continue;let store=localizedSources.get(el);if(!store||typeof store!=='object'){store={};localizedSources.set(el,store);}const current=el.getAttribute(attr);if(!store[attr]||current!==store[attr].last)store[attr]={source:current,last:current};const value=locale==='zh-CN'?store[attr].source:t(store[attr].source);if(current!==value)el.setAttribute(attr,value);store[attr].last=value;}}
if(state.route==='capture'){positionCaptureToolbar();positionCaptureDimension();}
}
let localizationObserver;
function startLocalization(){localizeDom();localizationObserver=new MutationObserver(()=>{localizationObserver.disconnect();localizeDom();localizationObserver.observe(document.body,{subtree:true,childList:true,characterData:true});});localizationObserver.observe(document.body,{subtree:true,childList:true,characterData:true});}
document.addEventListener('change',e=>{if(!e.target.matches('[data-locale-choice]'))return;draft.language=normalizeLanguage(e.target.value);if(state.route.startsWith('onboarding/')){saved.language=draft.language;try{const old=JSON.parse(localStorage.getItem('glint-prototype-v1')||'{}');localStorage.setItem('glint-prototype-v1',JSON.stringify({...old,language:draft.language}));}catch{}}render();});
window.addEventListener('languagechange',()=>{if(normalizeLanguage(draft.language)==='system')render();});
